\section*{Challenge 6: Better-Quasi-Ordering of Finite Graphs under Minor Relation}
\refstepcounter{section}

\begin{definition}[Cumulative Hierarchy over $Q$]
Given a set $Q$, we denote by $\mathcal P^*$ the set of nonempty subsets of $Q$. We define for each ordinal $\alpha$ a set $V^*_{\alpha}(Q)$ recursively as follows:
\begin{itemize}
\item $V^*_0(Q) := Q$.
\item $V^*_{\beta + 1} := \cal{P}^* V^*_{\beta}$
\item $V^*_{\lambda}(Q) := \dot \bigcup_{\alpha < \lambda} V^*_{\alpha}(Q)$ for any limit ordinal $\lambda$.
\end{itemize}

The class given by the union of all these sets is denoted $V^*(Q)$.
\end{definition}

\begin{definition}[$\alpha$-well-quasiordering]
Given a quasi-order $(Q,\le)$, we define a relation $\le^*$ on $V^*(Q)$ in terms of a 2-player game between Player I and Player II. A position in this game is a pair $(X,Y)$ with $X$ and $Y$ in $V^*(Q)$. If $X$ and $Y$ are both in $Q$ then this position is a win for Player II if $X \le Y$ and a win for Player I otherwise. If not, then Player I names a set $X'$, which must be $X$ itself if $X \in Q$ and otherwise must be an element of $X$. Then Player II also names a set $Y'$, which must be $Y$ itself if $Y \in Q$ and otherwise must be an element of $Y$. After this, the new position is $(X', Y')$. We define $X \le^* Y$ to mean that Player II has a winning strategy in this game with starting position $(X,Y)$.

We say that $(Q, \le)$ is {\em $\alpha$-well-quasiordered} if the restriction of this game to $V^*_{\alpha}(Q)$ is well-quasiordered.
\end{definition}

Note that $(Q, \le)$ is better-quasi-ordered if and only if it is $\omega_1$-well-quasi-ordered.

\begin{conjecture}
Let $r$ be an ordinal number. If $r$ is even, of the form $\alpha . 2$, then finite planar graphs are $\alpha$-well-quasi-ordered with respect to the minor relation. If $r$ is odd, of the form $\alpha . 2 + 1$, then finite graphs are $\alpha$-well-quasi-ordered.
\end{conjecture}

\section*{Challenge 7: The Sphere Packing Problem}
\refstepcounter{section}

\begin{definition}[Packing, density, sphere-packing constant]
Fix a dimension $d \in \N$.
\begin{enumerate}
\item A \emph{unit packing} of $\R^d$ is a set $C \subseteq \R^d$ of centres with $\lVert x - y \rVert \geq 2$ for all distinct $x,y \in C$; equivalently the open unit balls $B\ev{x,1}$, $x \in C$, are pairwise disjoint.
\item The \emph{upper density} of $C$ is
$$
\bar\delta\ev{C} := \limsup_{R \to \infty} \frac{\mathrm{vol}\!\ew{\textstyle\bigcup_{x \in C} B\ev{x,1} \cap B\ev{0,R}}}{\mathrm{vol}\!\ev{B\ev{0,R}}}.
$$
\item The \emph{sphere-packing constant} $\Delta_d := \sup_C \bar\delta\ev{C}$ is the supremum over all unit packings $C$; the supremum over packings whose centre set is a lattice is the \emph{lattice} packing constant $\Delta_d^{L}$.
\end{enumerate}
\end{definition}

\begin{openproblem}[The sphere-packing problem]
Determine the sphere-packing constant $\Delta_d$ for every dimension $d$. The value of $\Delta_d$ is known only for $d \in \{1,2,3,8,24\}$: the case $d = 3$ is the Kepler conjecture \cite{hales2005kepler}, while $d = 8$ and $d = 24$ were settled by Viazovska \cite{viazovska2017eight} and by Cohn, Kumar, Miller, Radchenko and Viazovska \cite{cohn2017twentyfour}. In each solved case the optimum is attained by a lattice ($\Z$, $A_2$, the FCC lattice, $E_8$, and the Leech lattice). The largest dimension solved is $d = 24$.
\end{openproblem}

The universal form posed below as a prove-or-disprove challenge asks whether lattices are always optimal: is $\Delta_d = \Delta_d^{L}$ for every $d$? This holds in every solved dimension, but is open in general and is widely expected to fail in high dimensions.

