\section*{Challenge 12: Koksma's Lower Bound for Partial Transversals}
\refstepcounter{section}

\begin{definition}[Latin square]
Let $S$ be a finite set with $|S| = n$. A \emph{latin square} on $S$ is a matrix $M : S \times S \rightarrow S$, whose rows and columns are both indexed by $S$ and whose entries lie in $S$, such that:
\begin{enumerate}
\item for every column $c \in S$, the map $r \mapsto M\ev{r,c}$ is injective (no symbol repeats within a column);
\item for every row $r \in S$, the map $c \mapsto M\ev{r,c}$ is injective (no symbol repeats within a row).
\end{enumerate}
The number $n = |S|$ is the \emph{size} of $M$.
\end{definition}

\begin{definition}[Partial transversal]
Define $\pi_1, \pi_2 : S \times S \rightarrow S$ by $\pi_1\ev{r,c} = r$ and $\pi_2\ev{r,c} = c$. A \emph{partial transversal} of a latin square $M$ is a set $T \subseteq S \times S$ of cells such that $\pi_1$, $\pi_2$ and $\ev{r,c} \mapsto M\ev{r,c}$ are each injective on $T$; that is, the cells of $T$ lie in pairwise distinct rows, in pairwise distinct columns, and carry pairwise distinct symbols.
\end{definition}

\begin{theorem}[Koksma \mbox{\cite{koksma}}]\label{koksmathm}
Every latin square of size $n \geq 7$ has a partial transversal of size at least $\dfrac{2n+1}{3}$.
\end{theorem}

