\section*{Challenge 17: Tutte's Wheel Theorem (Contraction Characterisation)}
\refstepcounter{section}

\begin{definition}[$3$-connected graph]
A finite simple graph $G$ on at least $4$ vertices is \emph{$3$-connected} if it remains connected after the removal of any two vertices; equivalently, it has no separating set of fewer than three vertices.
\end{definition}

\begin{definition}[Tutte sequence]
A \emph{Tutte sequence} for $G$ is a sequence of graphs $G_0 = K_4, G_1, \dots, G_n = G$ in which each $G_i$ is the contraction $G_{i+1} / xy$ of an edge $xy$ of $G_{i+1}$ whose two endpoints both have degree at least $3$ in $G_{i+1}$. Equivalently, $G$ is obtained from $K_4$ by a sequence of edge-uncontractions, each splitting a vertex into two adjacent vertices of degree at least $3$.
\end{definition}

\begin{theorem}[Tutte's Wheel Theorem \mbox{\cite{tutte1961}}]\label{tuttechar}
A finite graph $G$ is $3$-connected if and only if it admits a Tutte sequence, i.e. it can be built up from $K_4$ by edge-uncontractions of the above form.
\end{theorem}

