\section*{Challenge 20: Tutte's Wheel Theorem (Deletion/Contraction Reduction)}
\refstepcounter{section}

\begin{definition}[Wheel graph]
The \emph{wheel} $W_n$ ($n \geq 3$) is the graph obtained from a cycle on $n$ vertices (the \emph{rim}) by adding one further vertex (the \emph{hub}) joined to every vertex of the cycle.
\end{definition}

\begin{definition}[$3$-connected reduction edge]
Let $G$ be a finite $3$-connected simple graph and $e$ an edge of $G$. We say $e$ is a \emph{good reduction edge} if at least one of the deletion $G - e$ or the contraction $G / e$ is again a $3$-connected simple graph.
\end{definition}

\begin{theorem}[Tutte's Wheel Theorem \mbox{\cite{tutte1961}}]\label{tuttewheel}
Every finite $3$-connected simple graph that is not a wheel has a good reduction edge: an edge whose deletion or contraction yields again a $3$-connected simple graph.
\end{theorem}

This is the form of Tutte's wheel theorem used in inductive proofs of Kuratowski's theorem and in the structure theory of $3$-connected graphs.

