\section*{Challenge 22: Finite Graphs are Ubiquitous}
\refstepcounter{section}

\begin{definition}[Minor and disjoint copies]
A graph $H$ is a \emph{minor} of a graph $G$ if $H$ can be obtained from a subgraph of $G$ by contracting edges. Several copies of $H$ as minors of $G$ are \emph{disjoint} if their vertex sets are pairwise disjoint.
\end{definition}

\begin{definition}[Ubiquitous graph]
A graph $H$ is \emph{ubiquitous} (for the minor relation) if the following holds: whenever a graph $G$ contains, for every natural number $n$, at least $n$ pairwise disjoint copies of $H$ as a minor, then $G$ contains infinitely many pairwise disjoint copies of $H$ as a minor.
\end{definition}

\begin{theorem}[Ubiquity of finite graphs \mbox{\cite{carmesin_andreae}}]\label{ubiquityfinite}
Every finite graph $H$ is ubiquitous.
\end{theorem}

