\section*{Challenge 23: Failure of the Ubiquity Conjecture for Locally Finite Graphs}
\refstepcounter{section}

\begin{definition}[Minor, local finiteness, ubiquity]
A graph $H$ is a \emph{minor} of a graph $G$ if $H$ can be obtained from a subgraph of $G$ by contracting edges; copies of $H$ are \emph{vertex-disjoint} if their vertex sets are pairwise disjoint. A graph is \emph{locally finite} if every vertex has finite degree. A graph $H$ is \emph{ubiquitous} (for the minor relation) if, whenever a graph $G$ contains at least $n$ vertex-disjoint copies of $H$ as minors for every natural number $n$, then $G$ contains infinitely many vertex-disjoint copies of $H$ as minors.
\end{definition}

\begin{conjecture}[Andreae's Ubiquity Conjecture]
Every locally finite graph is ubiquitous.
\end{conjecture}

\begin{theorem}[Failure of ubiquity \mbox{\cite{carmesin_andreae}}]\label{ubiquityfail}
Andreae's ubiquity conjecture is false: there exists a locally finite (indeed countable) graph $H$, every vertex of which has finite degree, together with a host graph $G$ that contains $n$ vertex-disjoint $H$-minors for every $n$, yet does not contain infinitely many pairwise disjoint $H$-minors.
\end{theorem}

A concrete witness is the disjoint union of a \emph{barbell} (a $K_5$ and a $K_{3,3}$ joined by an edge) with a ray, embedded in a suitably decorated quarter-grid.

