\section*{Challenge 25: Vertex-transitive graphs of connectivity below five}
\refstepcounter{section}

\begin{definition}[Quasi-$4$-connected]
A finite graph $G$ is \emph{quasi-$4$-connected} if it is $4$-connected and every separation $(A,B)$ of $G$ of order at most $4$ has a side that is a single vertex outside the separator (that is, $|A\setminus B|=1$ or $|B\setminus A|=1$).
\end{definition}

\begin{definition}[Cycle-decomposition; cycle of $X$-bags]
A \emph{graph-decomposition} of $G$ modelled on a graph $H$ assigns to each node $h$ of $H$ a bag $V_h\subseteq V(G)$ so that $G=\bigcup_h G[V_h]$ and, for every vertex $v$, the nodes whose bag contains $v$ induce a connected subgraph of $H$~\cite{DJKK}. When $H$ is a cycle $C_\ell$ this is a \emph{cycle-decomposition}. Following~\cite{KurkofkaPlanken} (Definition 2.3), $G$ is a \emph{cycle of $K_4$-bags} (respectively of $C_4$-, $K_{2,2}$- or triangle-bags) if it has a cycle-decomposition whose adhesion-sets $V_i\cap V_j$ have size two, are disjoint (or independent) as specified, and whose bags or torsos are isomorphic to the named graph.
\end{definition}

\begin{theorem}[Kurkofka--Planken~\cite{KurkofkaPlanken}]
A quasi-$4$-connected finite graph $G$ is vertex-transitive if and only if $G$ is one of:
\begin{enumerate}
\item a $(\geq 4)$-regular quasi-$5$-connected vertex-transitive graph;
\item a $3$-regular $2$-quasi-$5$-connected vertex-transitive graph;
\item a $K_4$- or $C_4$-expansion of a quasi-$5$-connected $4$-regular arc-transitive graph;
\item a cycle of $K_4$-bags;
\item a cycle alternating between $K_4$-bags and $C_4$-bags;
\item a cycle of triangle-bags;
\item a cycle alternating between $K_{2,2}$-bags and $C_4$-torsos;
\item a cycle of $C_4$-bags, or the prism $K_3\,\square\,K_2$;
\item a cycle of $K_{2,2}$-bags, or a $K_4$/$C_4$-expansion of one;
\item the line graph of the cube $C_4\,\square\,K_2$, or one of its named $K_4$/$C_4$-expansions.
\end{enumerate}
\end{theorem}

