\section*{Challenge 27: Seymour's Second Neighbourhood Conjecture}
\refstepcounter{section}

\begin{definition}[Oriented graph]
An \emph{oriented graph} is a pair $G = \ev{V, \to}$ where $V$ is a finite vertex set and ${\to} \subseteq V \times V$ is a relation that is \emph{loopless} ($v \not\to v$ for all $v$) and has \emph{no $2$-cycles} (if $u \to v$ then $v \not\to u$). Equivalently, $G$ is an orientation of a finite simple graph.
\end{definition}

\begin{definition}[First and second out-neighbourhoods]
Let $G = \ev{V, \to}$ be an oriented graph and $v \in V$.
\begin{enumerate}
\item The \emph{first out-neighbourhood} is $N^{+}\ev{v} := \{\, w \in V : v \to w \,\}$.
\item The \emph{second out-neighbourhood} is
$$
N^{++}\ev{v} := \{\, w \in V : w \neq v,\ v \not\to w,\ \text{and } \exists u \in V \text{ with } v \to u \to w \,\},
$$
the set of vertices at directed distance exactly two from $v$.
\end{enumerate}
\end{definition}

\begin{conjecture}[Seymour's Second Neighbourhood Conjecture \mbox{\cite{deanlatka}}]\label{seymour}
Every finite oriented graph $G = \ev{V, \to}$ has a vertex $v$ whose second out-neighbourhood is at least as large as its first:
$$
\bigl| N^{+}\ev{v} \bigr| \ \leq\ \bigl| N^{++}\ev{v} \bigr| .
$$
\end{conjecture}

The conjecture, due to Paul Seymour around 1990, is open in general. The special case of \emph{tournaments} (orientations of complete graphs) is Dean's conjecture, proved by Fisher \cite{fisher} via a probabilistic/Farkas argument; Havet and Thomass\'e later gave a combinatorial proof using median orders. For general oriented graphs only partial results are known --- for instance, every oriented graph has a vertex $v$ with $|N^{++}\ev{v}| \geq \gamma\, |N^{+}\ev{v}|$ for $\gamma$ the real root of $2x^{3} + x^{2} - 1 = 0$ ($\gamma \approx 0.657$) \cite{chenshenyuster}.

