\section*{Challenge 96: Characteristic and Matching Polynomials of a Uniform Hypertree}
\refstepcounter{section}

\begin{definition}[Hypertrees, matching polynomial, boundary]
An $r$-uniform hypergraph is a finite family of $r$-element edges; an \emph{$r$-tree} is obtained from a single edge by repeatedly attaching a new edge sharing exactly one vertex with the existing hypergraph. The \emph{matching polynomial} of an $r$-uniform hypergraph $H$ on $n$ vertices is $\varphi_H(\lambda) = \sum_k (-1)^k m_k(H)\,\lambda^{\,n - rk}$ where $m_k$ counts $k$-matchings. For a subgraph $H$ of $T$, the \emph{boundary} $\partial H$ is the set of edges of $T$ not in $H$ that meet $H$. The characteristic polynomial $\varphi_T$ of the adjacency tensor is defined through the resultant of the eigenvalue system, represented in Lean by polynomial division of the two Macaulay determinants. The general resultant identity and exactness of this division remain to be formalized; the ordinary-graph case is verified independently. The edge-set model here treats hypertrees with at least one edge.
\end{definition}

\begin{theorem}[Li--Su--Fallat, Theorem 4.10 \cite{li2023hypertree}]\label{hypertree}
Let $T$ be an $r$-tree with $m$ edges, $r \ge 2$, $b = (r-1)^{r-1}$, $c = r^{r-2}$. Then
$$\varphi_T(\lambda) = \prod_{H} \varphi_H(\lambda)^{a_H}, \qquad a_H = b^{\,m - e(H) - |\partial H|}\, c^{\,e(H)}\, (b - c)^{|\partial H|},$$
the product over the connected subgraphs $H$ of $T$, single vertices included (with $\varphi = \lambda$ and boundary the star of the vertex).
\end{theorem}

For $r = 2$ the exponents collapse and the identity is the classical fact that the characteristic and matching polynomials of a tree coincide.

