\section*{Challenge 97: Algebraic Connectivity of Token Graphs with a Cut Clique}
\refstepcounter{section}

\begin{definition}[Token graphs, algebraic connectivity]
The \emph{$k$-token graph} $F_k(G)$ of a graph $G$ has as vertices the $k$-subsets of $V(G)$, two being adjacent when their symmetric difference is an edge of $G$. The \emph{algebraic connectivity} $\alpha(G)$ is the second smallest eigenvalue of the Laplacian of $G$, characterised by the Rayleigh quotient over vectors orthogonal to the all-ones vector.
\end{definition}

\begin{theorem}[Song--Dalf\'o--Fiol--Zhang, Theorem 5.3 \cite{song2024token}]\label{tokencut}
Let $G$ be a graph on $n$ vertices with a clique $K_r$, $r \ge 1$, each of whose vertices is adjacent to every vertex outside the clique (so the clique has degree $r(n-r)$) and whose removal disconnects $G$. Then $\alpha(G) = \alpha(F_k(G)) = r$ for every $1 \le k \le n-1$.
\end{theorem}

For $r = 1$ this is the theorem of Barik and Verma on cut vertices of degree $n-1$. Challenge 69 records the general equality $\alpha(F_k(G)) = \alpha(G)$ (Aldous' spectral gap theorem); the present theorem identifies the common value for the cut-clique family.

