\section*{Challenge 100: The Tutte Decomposition of 2-Connected Graphs}
\refstepcounter{section}

\begin{definition}[Separations, tree-decompositions, torsos]
A \emph{separation} of a finite graph $G$ is a pair $(A,B)$ of vertex sets covering $V(G)$ with no edge between $A \setminus B$ and $B \setminus A$ and both differences nonempty; its \emph{order} is $|A \cap B|$. Two separations are \emph{nested} if a side of one contains a side of the other (up to exchanging sides), and a $2$-separation is \emph{totally nested} if it is nested with every $2$-separation. A \emph{tree-decomposition} assigns bags to the nodes of a tree so that every vertex and edge lies in a bag and the nodes containing a vertex form a subtree; the \emph{adhesion} of a tree edge is the intersection of its two bags, and the \emph{torso} of a node is its bag with every adhesion set completed to a clique.
\end{definition}

\begin{theorem}[Bourneuf--Planken, Theorem 1.1 \cite{bourneufplanken2025tutte}]\label{tutte}
Every $2$-connected finite graph $G$ has a tree-decomposition of adhesion two whose torsos are $3$-connected graphs, cycles or $K_2$, and whose tree edges induce exactly the totally nested $2$-separations of $G$.
\end{theorem}

This is the Cunningham--Edmonds structure computed by the paper's algorithm; the $O(n+m)$ running-time bound concerns the word-RAM model and is not part of the formal statement.

