\section*{Challenge 101: Upper Clique Transversals via Dual Conformality}
\refstepcounter{section}

\begin{definition}[Clique transversals, conformality, duality]
A \emph{clique transversal} of a graph $G$ is a vertex set meeting every maximal clique; $\tau_c^+(G)$ is the largest size of an inclusion-minimal clique transversal. A hypergraph is \emph{conformal} if every set of vertices that is pairwise contained in hyperedges lies in a hyperedge, and \emph{dually conformal} if its dual hypergraph (the minimal transversals) is conformal. The \emph{co-occurrence graph} of a hypergraph joins two vertices lying in a common hyperedge.
\end{definition}

\begin{theorem}[Boros--Gurvich--Milani\v{c}--Uno, Theorem 4.1 \cite{borosgurvichmilanicuno2023conformal}]\label{uct}
Let $k \ge 2$ and let $\mathcal H$ be the hypergraph of minimal clique transversals of $G$ of size less than $k$. Then $\tau_c^+(G) \ge k$ if and only if $\mathcal H$ is not dually conformal or $G$ is not the co-occurrence graph of $\mathcal H^d$.
\end{theorem}

The paper derives from this criterion an algorithm running in time $O(|V|^{3k-3})$; the running-time bound is not part of the formal statement.

