\section*{Challenge 102: The Full Rank Condition for Sparse Random Matrices}
\refstepcounter{section}

\begin{definition}[The random matrix model]
Let $d$ and $k \ge 3$ be probability distributions on the integers (\emph{degree laws}) with $\mathbb E[d^{2+\eta}] + \mathbb E[k^{2+\eta}] < \infty$ for some $\eta > 0$, and let $\mathfrak d$, $\mathfrak k$ be the gcds of their supports. The matrix $\mathbb A = \mathbb A_n(d,k,\chi)$ over a finite field $\mathbb F$ of order $q$ coprime to $\mathfrak d$ has $n$ columns and $m \sim \mathrm{Po}(\mathbb E[d]\, n/\mathbb E[k])$ rows; its nonzero pattern is a uniformly random simple bipartite graph with column degrees drawn from $d$ and row degrees from $k$, and its nonzero entries are independent with law $\chi$ on $\mathbb F \setminus \{0\}$. The function $\Phi$ of the paper's (1.2) is built from the generating functions of $d$ and $k$.
\end{definition}

\begin{theorem}[Coja-Oghlan, Gao, Hahn-Klimroth, Lee, M\"uller, Rolvien, Theorem 1.1 \cite{cojaoghlan2021fullrank}]\label{fullrank}
If $\Phi(z) < \Phi(0)$ for all $0 < z \le 1$, then $\mathbb A_n(d,k,\chi)$ has full row rank over $\mathbb F$ with high probability as $n \to \infty$ along multiples of $\mathfrak k$.
\end{theorem}

