\section*{Challenge 103: The Dimension of Co-Sparse Random Bipartite Graph Orders}
\refstepcounter{section}

\begin{definition}[Random bipartite graph orders, dimension]
For the random bipartite graph $B(n,n,p)$ on parts $A = [n]$ and $B = \{n+1,\dots,2n\}$, in which each pair $ab$ with $a \in A$, $b \in B$ is an edge independently with probability $p$, the order $P_{B(n,n,p)}$ has $a \le b$ exactly when $ab$ is an edge. The \emph{dimension} of a poset is the least number of linear extensions whose intersection is the poset.
\end{definition}

\begin{theorem}[Gao--Kumar, Theorem 9 \cite{gaokumar2025dimension}]\label{dimension}
Let $q = 1-p$. (a) If $q = O(1/n)$ and $q = \omega(1/n^2)$, then asymptotically almost surely $\dim P_{B(n,n,p)} = \Theta(n^2 q)$ and $n - \dim P_{B(n,n,p)} = \Omega(n)$. (b) If $q = \omega(1/n)$ and $q \le n^{-1+1/7}$, then asymptotically almost surely $\dim P_{B(n,n,p)} = (1-o(1))\,n$.
\end{theorem}

