\section*{Challenge 104: Sandwiching Random Regular Graphs between Erd\H{o}s--R\'enyi Graphs}
\refstepcounter{section}

\begin{definition}[The models, sandwich couplings]
$G(n,d)$ is the uniformly random $d$-regular simple graph on $[n]$ ($dn$ even), $G(n,p)$ the Erd\H{o}s--R\'enyi graph. A \emph{sandwich coupling} is a joint distribution of $G_* \sim G(n,p_*)$, $G \sim G(n,d)$, $G^* \sim G(n,p^*)$ with $G_* \subseteq G \subseteq G^*$ with probability $1-o(1)$.
\end{definition}

\begin{theorem}[Gao--Isaev--P\'erez-Gim\'enez, Theorem 1.5 \cite{gaoisaevperezgimenez2025sandwich}]\label{sandwich}
Let $d = d(n)$ with $dn$ even and $d \le n-1$. (a) If $d = n - O(\log^4 n)$ there are $p_*, p^* = (1+o(1))d/n$ and a sandwich coupling. (b) If $d \gg \log n$ and $d = O(\log^4 n)$ the same holds with $p_* = (1-o(1))d/n$ and $p^* = (8+o(1))d/n$. (c) If $d = o(\log n)$, for every fixed $\varepsilon > 0$ there are sandwich couplings with $p_* = (1-\varepsilon)d/n$ and $p^* = (1+\varepsilon)d/n$, up to the error terms stated in the paper.
\end{theorem}

Part (a) resolves the Kim--Vu sandwich conjecture in the regime of very large degrees; the paper's constructions use the configuration model and unions of perfect matchings.

