\section*{Challenge 106: Connectivity Thresholds of the Pre- and Post-Positional Semi-Random Processes}
\refstepcounter{section}

\begin{definition}[The two processes]
In the \emph{post-positional} semi-random process a vertex $u_t$ is offered uniformly at random and the player then chooses $v_t$; in the \emph{pre-positional} process the player chooses $v_t$ first and $u_t$ is then uniform and independent of $v_t$. In both, the edge $u_t v_t$ is added in round $t$ (loops and multiple edges may arise; properties concern the underlying simple graph).
\end{definition}

\begin{theorem}[Gao--Koerts, Theorem 1.1 \cite{gaokoerts2023positional}]\label{positional}
For every fixed $k \ge 1$ there is $\alpha_k \in \mathbb R$ such that for every $\varepsilon > 0$: no strategy in either process builds a $k$-connected graph within $(\alpha_k - \varepsilon)n$ rounds asymptotically almost surely, while strategies in both processes build a $k$-connected graph within $(\alpha_k+\varepsilon)n$ rounds asymptotically almost surely. Here $\alpha_1 = 1$ and, for $k \ge 2$, $\alpha_k$ is the constant of Wormald's min-degree process.
\end{theorem}

